"""Claim fact extraction port — Gemini-free. Maps validated facts to canonical Claim."""

from __future__ import annotations

from datetime import date, datetime
from typing import Any, Protocol

from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator

from app.domain.entities import Claim, ClaimLine
from app.domain.money import Money

# Hallucinated adjudication fields must fail closed (D30). Unknown extra keys such as
# quantity are ignored — ClaimLine has no units field (D11).
_ADJUDICATION_FIELD_NAMES = frozenset(
    {
        "outcome",
        "approval",
        "denial",
        "approved",
        "denied",
        "allowed",
        "allowed_amount",
        "above_allowed",
        "deductible",
        "deductible_applied",
        "plan_paid",
        "denied_amount",
        "reason",
        "reason_code",
        "reason_codes",
        "reasons",
        "explanation",
        "trace",
        "benefit_limit",
        "annual_limit",
        "visit_limit",
        "coverage",
        "covered",
        "excluded",
    }
)

# JSON Schema sent to Gemini structured output. Keep this the source for the API
# contract; Pydantic below is the validator. [PROPOSED] schema shape.
EXTRACTION_JSON_SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "member_id": {"type": "string"},
        "lines": {
            "type": "array",
            "minItems": 1,
            "items": {
                "type": "object",
                "properties": {
                    "line_number": {"type": "integer", "minimum": 1},
                    "provider_id": {"type": "string"},
                    "service_code": {"type": "string"},
                    "service_date": {
                        "type": "string",
                        "description": "ISO 8601 date YYYY-MM-DD",
                    },
                    "billed_amount_minor_units": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "Integer minor units (e.g. paise); do not guess",
                    },
                    "diagnosis_code": {"type": "string"},
                },
                "required": [
                    "line_number",
                    "provider_id",
                    "service_code",
                    "service_date",
                    "billed_amount_minor_units",
                    "diagnosis_code",
                ],
            },
        },
    },
    "required": ["member_id", "lines"],
}


class ClaimExtractionError(Exception):
    """Extraction could not produce a canonical Claim. No facts were invented."""


class ClaimExtractionValidationError(ClaimExtractionError):
    """Malformed output, missing required fields, or invalid types."""


class ClaimExtractionApiError(ClaimExtractionError):
    """Gemini / HTTP client failure. Message must never include the API key."""


class ExtractedClaimLineFacts(BaseModel):
    """Line facts Gemini may fill — a subset of ClaimLine, no computed amounts."""

    model_config = ConfigDict(extra="ignore")

    line_number: int = Field(ge=1)
    provider_id: str = Field(min_length=1)
    service_code: str = Field(min_length=1)
    service_date: date
    billed_amount_minor_units: int = Field(ge=0)
    diagnosis_code: str = Field(min_length=1)

    @field_validator("provider_id", "service_code", "diagnosis_code")
    @classmethod
    def _strip_required_text(cls, value: str) -> str:
        stripped = value.strip()
        if not stripped:
            raise ValueError("must not be blank")
        return stripped


class ExtractedClaimFacts(BaseModel):
    """Claim facts Gemini may fill — no outcome, payment, or reason codes."""

    model_config = ConfigDict(extra="ignore")

    member_id: str = Field(min_length=1)
    lines: list[ExtractedClaimLineFacts] = Field(min_length=1)

    @field_validator("member_id")
    @classmethod
    def _strip_member_id(cls, value: str) -> str:
        stripped = value.strip()
        if not stripped:
            raise ValueError("must not be blank")
        return stripped


class ClaimExtractor(Protocol):
    """Application port. Implementations live in infrastructure; domain does not see this."""

    def extract(
        self,
        unstructured_text: str,
        *,
        claim_id: str,
        submitted_at: datetime,
    ) -> Claim:
        """Return a canonical Claim. Must not adjudicate."""


def parse_extracted_facts(payload: object) -> ExtractedClaimFacts:
    """Validate a parsed JSON object. Does not invent missing fields."""
    if not isinstance(payload, dict):
        raise ClaimExtractionValidationError("extracted payload must be a JSON object")
    _reject_adjudication_fields(payload)
    try:
        return ExtractedClaimFacts.model_validate(payload)
    except ValidationError as exc:
        raise ClaimExtractionValidationError("extracted facts failed schema validation") from exc


def to_canonical_claim(
    facts: ExtractedClaimFacts,
    *,
    claim_id: str,
    submitted_at: datetime,
) -> Claim:
    """Map validated facts to the existing Claim / ClaimLine model.

    claim_id and submitted_at are assigned by the caller, not by Gemini.
    Line ids are derived as ``{claim_id}-L{line_number}``.
    """
    if not claim_id or not claim_id.strip():
        raise ClaimExtractionValidationError("claim_id must be non-empty")
    lines = tuple(
        ClaimLine(
            id=f"{claim_id}-L{line.line_number}",
            claim_id=claim_id,
            line_number=line.line_number,
            provider_id=line.provider_id,
            service_code=line.service_code,
            service_date=line.service_date,
            billed_amount=Money(line.billed_amount_minor_units),
            diagnosis_code=line.diagnosis_code,
        )
        for line in facts.lines
    )
    try:
        return Claim(
            id=claim_id,
            member_id=facts.member_id,
            submitted_at=submitted_at,
            lines=lines,
        )
    except ValueError as exc:
        raise ClaimExtractionValidationError("extracted facts are not a valid Claim") from exc


def _reject_adjudication_fields(payload: dict[str, Any]) -> None:
    present = _ADJUDICATION_FIELD_NAMES.intersection(payload)
    if present:
        raise ClaimExtractionValidationError(
            "extraction included adjudication fields, which Gemini must not produce"
        )
    lines = payload.get("lines")
    if not isinstance(lines, list):
        return
    for line in lines:
        if isinstance(line, dict) and _ADJUDICATION_FIELD_NAMES.intersection(line):
            raise ClaimExtractionValidationError(
                "extraction included adjudication fields, which Gemini must not produce"
            )

"""Gemini-backed claim extractor. Domain must never import this module."""

from __future__ import annotations

import json
import os
from datetime import datetime
from typing import Any

from google import genai

from app.application.claim_extractor import (
    EXTRACTION_JSON_SCHEMA,
    ClaimExtractionApiError,
    ClaimExtractionError,
    ClaimExtractionValidationError,
    ExtractedClaimFacts,
    parse_extracted_facts,
    to_canonical_claim,
)
from app.domain.entities import Claim

# [PROPOSED] Default model for structured extraction. Override via constructor.
DEFAULT_GEMINI_MODEL = "gemini-2.5-flash"

_API_KEY_ENV = "GEMINI_API_KEY"

_EXTRACT_INSTRUCTIONS = (
    "Extract claim facts from the unstructured text. "
    "Fill only member_id and line items: line_number, provider_id, service_code, "
    "service_date (YYYY-MM-DD), billed_amount_minor_units (integer minor units), "
    "diagnosis_code. "
    "If a required fact is not clearly present, omit it; do not guess or invent values. "
    "Do not decide coverage, pricing, deductible, limits, payment, outcome, or reason codes. "
    "Do not include explanations."
)


class GeminiClaimExtractor:
    """Infrastructure adapter: unstructured text → Gemini JSON → validated Claim."""

    def __init__(
        self,
        *,
        client: Any | None = None,
        model: str = DEFAULT_GEMINI_MODEL,
        api_key: str | None = None,
    ) -> None:
        self._model = model
        self._client = client if client is not None else _build_client(api_key)

    def extract(
        self,
        unstructured_text: str,
        *,
        claim_id: str,
        submitted_at: datetime,
    ) -> Claim:
        facts = self.extract_facts(unstructured_text)
        return to_canonical_claim(facts, claim_id=claim_id, submitted_at=submitted_at)

    def extract_facts(self, unstructured_text: str) -> ExtractedClaimFacts:
        if not unstructured_text or not unstructured_text.strip():
            raise ClaimExtractionValidationError("unstructured text is empty")
        payload = self._generate_json_payload(unstructured_text)
        return parse_extracted_facts(payload)

    def _generate_json_payload(self, unstructured_text: str) -> object:
        try:
            response = self._client.models.generate_content(
                model=self._model,
                contents=_extraction_contents(unstructured_text),
                config={
                    "response_mime_type": "application/json",
                    "response_json_schema": EXTRACTION_JSON_SCHEMA,
                    "temperature": 0,
                },
            )
        except ClaimExtractionError:
            raise
        except Exception as exc:
            raise ClaimExtractionApiError("Gemini request failed") from exc

        raw = getattr(response, "text", None)
        if not raw or not str(raw).strip():
            raise ClaimExtractionValidationError("Gemini returned empty output")
        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ClaimExtractionValidationError("malformed Gemini output") from exc


def _build_client(api_key: str | None) -> Any:
    key = api_key if api_key is not None else os.environ.get(_API_KEY_ENV)
    if not key:
        raise ClaimExtractionApiError("GEMINI_API_KEY is not set")
    try:
        return genai.Client(api_key=key)
    except Exception as exc:
        raise ClaimExtractionApiError("Gemini client could not be created") from exc


def _extraction_contents(unstructured_text: str) -> str:
    return f"{_EXTRACT_INSTRUCTIONS}\n\nUnstructured claim:\n{unstructured_text}"
